script:
// Mask sensitive fields and add OTP unmask buttons
// Applies to: custom_sa_id_number, mobile

const PROTECTED_FIELDS = [
  { fieldname: 'custom_sa_id_number', label: 'SA ID Number' },
  { fieldname: 'mobile', label: 'Mobile' },
];

function maskValue(value, fieldname) {
  if (!value) return '—';
  if (fieldname === 'custom_sa_id_number') {
    return `*** *** ${String(value).slice(-4)}`;
  }
  if (fieldname === 'mobile') {
    return `+27 ** *** ${String(value).slice(-3)}`;
  }
  return `${String(value)[0]}${'*'.repeat(Math.max(0, String(value).length - 1))}`;
}

function addUnmaskButton(frm, fieldname, label) {
  // Use a custom HTML field or description trick to show masked + button
  const field = frm.get_field(fieldname);
  if (!field) return;

  const rawValue = frm.doc[fieldname];
  if (!rawValue) return;

  // Replace the input display with masked text + View button
  const $wrap = $(field.$wrapper).find('.control-value, .like-disabled-input');
  if (!$wrap.length) return;

  if ($wrap.find('.mp-unmask-btn').length) return; // already added

  const masked = maskValue(rawValue, fieldname);
  $wrap.text(masked);

  const $btn = $(`
    <button class="btn btn-xs btn-default mp-unmask-btn" style="margin-left:8px">
      <i class="fa fa-eye"></i> View
    </button>
  `);

  $wrap.append($btn);

  $btn.on('click', function () {
    initiateUnmask(frm, fieldname, label);
  });
}

function initiateUnmask(frm, fieldname, label) {
  frappe.call({
    method: 'medic_plus.api.data_access.request_unmask',
    args: {
      doctype: frm.doctype,
      docname: frm.docname,
      field: fieldname,
    },
    callback(r) {
      if (!r.message) return;
      const requestName = r.message.request;

      // Build two-input dialog
      const fields = [
        {
          label: 'Your verification code',
          fieldname: 'requester_otp',
          fieldtype: 'Data',
          reqd: 1,
          description: 'Check your email/SMS for a 6-digit code.',
        },
        {
          label: 'Patient verification code',
          fieldname: 'patient_otp',
          fieldtype: 'Data',
          reqd: 1,
          description:
            'Ask the patient to read the 6-digit code from their email/SMS.',
        },
      ];

      // On staging (developer_mode), pre-fill OTPs for QA convenience
      const devHint =
        r.message._dev_requester_otp
          ? `<p class="text-muted" style="font-size:0.85em">⚙ Dev mode OTPs — Yours: <strong>${r.message._dev_requester_otp}</strong> | Patient: <strong>${r.message._dev_patient_otp}</strong></p>`
          : '';

      const d = new frappe.ui.Dialog({
        title: `Verify Access — ${label}`,
        fields,
        primary_action_label: 'Confirm',
        primary_action(values) {
          frappe.call({
            method: 'medic_plus.api.data_access.verify_unmask',
            args: {
              request_name: requestName,
              requester_otp: values.requester_otp,
              patient_otp: values.patient_otp,
            },
            callback(res) {
              if (res.message && res.message.value !== undefined) {
                frappe.show_alert(
                  { message: `${label}: ${res.message.value}`, indicator: 'green' },
                  15
                );
                d.hide();
              }
            },
          });
        },
      });

      if (devHint) {
        d.$wrapper.find('.modal-body').prepend(devHint);
      }

      d.show();
    },
  });
}

frappe.ui.form.on('Patient', {
  refresh(frm) {
    if (frm.is_new()) return;
    // Only mask for non-admin staff; patients see their own data via portal
    const userRoles = frappe.user.get_roles();
    const isAdmin = userRoles.includes('Healthcare Administrator');
    const isPatient = userRoles.includes('Patient');
    if (isPatient) return; // patients see their own data unmasked

    PROTECTED_FIELDS.forEach(({ fieldname, label }) => {
      // Only add read-only display override — don't break the actual field value
      addUnmaskButton(frm, fieldname, label);
    });
  },
});

frappe.ui.form.on('Healthcare Practitioner', {
  refresh(frm) {
    if (frm.is_new()) return;
    renderAssociatedPractices(frm);
  },
});

function renderAssociatedPractices(frm) {
  frappe.call({
    method: 'frappe.client.get_list',
    args: {
      doctype: 'Practice Doctor',
      filters: [['practitioner', '=', frm.doc.name]],
      fields: ['parent', 'is_primary'],
      limit: 50,
    },
    callback(r) {
      if (!r.message || !r.message.length) return;

      const rows = r.message;
      const practiceNames = rows.map(row => row.parent);

      frappe.call({
        method: 'frappe.client.get_list',
        args: {
          doctype: 'Practice',
          filters: [['name', 'in', practiceNames]],
          fields: ['name', 'practice_name', 'slug'],
          limit: 50,
        },
        callback(pr) {
          if (!pr.message) return;
          const practiceMap = {};
          pr.message.forEach(p => { practiceMap[p.name] = p; });

          let html = '<div style="display:flex;flex-wrap:wrap;gap:8px;padding:4px 0;">';
          rows.forEach(row => {
            const p = practiceMap[row.parent];
            if (!p) return;
            const badge = row.is_primary
              ? '<span style="font-size:0.7rem;background:#dbeafe;color:#1d4ed8;border-radius:4px;padding:1px 6px;margin-left:6px;">Primary</span>'
              : '';
            html += `<a href="/app/practice/${encodeURIComponent(p.name)}" style="display:inline-flex;align-items:center;padding:6px 12px;border:1px solid #e5e7eb;border-radius:6px;text-decoration:none;color:inherit;font-size:0.9rem;">${frappe.utils.escape_html(p.practice_name)}${badge}</a>`;
          });
          html += '</div>';

          frm.set_df_property('associated_practices_html', 'options', html);
          frm.refresh_field('associated_practices_html');
        },
      });
    },
  });
}
